import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association (p < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
        p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
        if p_val < 0.01:
            strong_features.append((fid, p_val))

    # Sort by p-value
    strong_features.sort(key=lambda x: x[1])

    # Select top 3 features as drivers (smaller model)
    drivers = tuple(fid for fid, _ in strong_features[:3])

    # Handle correlated features by keeping only parents
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Remove near-duplicates (keep the one with better p-value)
    to_remove = set()
    for (fid1, fid2), corr in correlations.items():
        if fid1 in to_remove or fid2 in to_remove:
            continue
        # Check which feature is more associated with outcome
        idx1 = feats.column(fid1)
        idx2 = feats.column(fid2)
        t1 = feats.x[:, idx1].T @ feats.y / np.sqrt(np.var(feats.x[:, idx1]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
        t2 = feats.x[:, idx2].T @ feats.y / np.sqrt(np.var(feats.x[:, idx2]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
        if abs(t1) > abs(t2):
            to_remove.add(fid2)
        else:
            to_remove.add(fid1)

    # Build columns list (limit to 5 features total)
    columns = [fid for fid in feats.ids if fid not in to_remove and fid not in drivers][:5]

    # Add interaction terms for top 2 features only
    products = []
    for i, fid1 in enumerate(columns[:2]):
        for j, fid2 in enumerate(columns[:2]):
            if i < j:
                products.append((fid1, fid2))

    # Create loadings dict using standardized values
    loadings = {}
    for fid in columns:
        idx = feats.column(fid)
        # Use correlation with outcome as weight
        cor = np.corrcoef(feats.x[:, idx], feats.y)[0, 1]
        loadings[fid] = cor

    return Design(
        drivers=drivers,
        columns=columns,
        products=products,
        loadings=loadings
    )

